import zipfile
import re
import xml.etree.ElementTree as ET

NS = {'m': 'http://schemas.openxmlformats.org/spreadsheetml/2006/main'}

path = 'budget.xlsx'
with zipfile.ZipFile(path) as z:
    names = z.namelist()
    print("Archive entries (first 20):")
    for n in names[:20]:
        print(" ", n)

    shared = {}
    if 'xl/sharedStrings.xml' in names:
        root = ET.fromstring(z.read('xl/sharedStrings.xml'))
        for i, si in enumerate(root.findall('m:si', NS)):
            shared[i] = ''.join(t.text or '' for t in si.iter('{http://schemas.openxmlformats.org/spreadsheetml/2006/main}t'))

    wb_root = ET.fromstring(z.read('xl/workbook.xml'))
    sheets = [(s.get('name'), s.get('{http://schemas.openxmlformats.org/officeDocument/2006/relationships}id'))
              for s in wb_root.find('m:sheets', NS)]
    print("\nWorkbook sheets:", sheets)

    rels = ET.fromstring(z.read('xl/_rels/workbook.xml.rels'))
    rel_map = {r.get('Id'): r.get('Target') for r in rels}

    for name, rid in sheets:
        target = rel_map[rid]
        if not target.startswith('xl/'):
            target = 'xl/' + target.lstrip('/')
        root = ET.fromstring(z.read(target))
        print(f"\n=== Sheet: {name} ({target}) ===")
        for row in root.find('m:sheetData', NS):
            cells = []
            for c in row.findall('m:c', NS):
                ref = c.get('r')
                t = c.get('t')
                v = c.find('m:v', NS)
                val = v.text if v is not None else None
                if t == 's' and val is not None:
                    val = shared.get(int(val), '')
                cells.append((ref, val))
            if cells:
                print(cells)

