import zipfile
import re
import xml.etree.ElementTree as ET
from collections import OrderedDict

MAIN = '{http://schemas.openxmlformats.org/spreadsheetml/2006/main}'
TAG_T = MAIN + 't'

def cell_value(c, shared):
    t = c.get('t')
    v = c.find(MAIN + 'v')
    raw = v.text if v is not None else None
    if t == 's' and raw is not None:
        return shared.get(int(raw), '')
    if t == 'inlineStr':
        return ''.join(x.text or '' for x in c.iter(TAG_T))
    return raw  # numeric or formula-str raw text

def to_float(s):
    try:
        return float(str(s).replace(',', '').strip())
    except (TypeError, ValueError):
        return None

with zipfile.ZipFile('budget.xlsx') as z:
    root = ET.fromstring(z.read('xl/worksheets/sheet1.xml'))
    shared = {}
    if 'xl/sharedStrings.xml' in z.namelist():
        sroot = ET.fromstring(z.read('xl/sharedStrings.xml'))
        for i, si in enumerate(sroot.findall(MAIN + 'si')):
            shared[i] = ''.join(t.text or '' for t in si.iter(TAG_T))

    grid = {}
    for row in root.find(MAIN + 'sheetData'):
        for c in row.findall(MAIN + 'c'):
            ref = c.get('r')
            m = re.match(r'([A-Z]+)(\d+)', ref)
            if not m:
                continue
            col, rnum = m.group(1), int(m.group(2))
            grid[(rnum, col)] = cell_value(c, shared)

# Expense line items: rows 11-22, column C (section 'EXPENSES' at A10, 'Total Expenses' at A23)
by_cat = OrderedDict()
expense_total = 0.0
for r in range(11, 23):
    cat = str(grid.get((r, 'A'), '')).strip()
    item = str(grid.get((r, 'B'), '')).strip()
    amt = to_float(grid.get((r, 'C')))
    if amt is not None:
        by_cat.setdefault(cat, [])
        by_cat[cat].append((item, amt))
        expense_total += amt
        print(f"{r:>2} {cat:<16} {item:<18} {amt:>10.2f}")

print("\nBy category:")
for cat, items in by_cat.items():
    print(f"  {cat:<16} {sum(a for _, a in items):>10.2f}")

print(f"\nTOTAL EXPENSES: {expense_total:.2f}")

